namespace docking.widgets.tree.tasks;





using docking.widgets.tree;
using ghidra.util.exception;
using ghidra.util.task;

public class GTreeExpandAllTask : GTreeTask {
	// The MAX number of nodes to expand. Expanding nodes is fairly expensive and must
	// be done in the Swing thread. So to avoid hanging up the GUI, we limit it to
	// a reasonable number.  Also, this task is primarily used to show filter results
	// and if you have too many results, you probably aren't going to look at them
	// all anyway.
	private static readonly int MAX = 1000;
	private GTreeNode node;

	public GTreeExpandAllTask(GTree tree, GTreeNode node) : base(tree)
    {
		this.node = node;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		monitor.initialize(1000);
		monitor.setMessage("Expanding nodes...");
		try {
			expandNode(node, true, monitor);
		}
		catch (CancelledException e) {
			// Not everything expanded which is ok
		}
	}

	/**
	 * Expand the specified parent tree node.
	 * @param parent the tree node to be expanded
	 * @param force if parent node has auto-expand disabled 
	 * (see {@link GTreeNode#isAutoExpandPermitted()}) passing true will force such a node to 
	 * expand, false will respect this restriction and not expand the parent node.
	 * @param monitor task monitor
	 * @throws CancelledException if task cancelled
	 */
	protected void expandNode(GTreeNode parent, bool force, TaskMonitor monitor)
    {
		// only expand MAX number of nodes.
		if (monitor.getProgress() >= MAX) {
			return;
		}
		if (parent.isLeaf()) {
			return;
		}
		if (!force && !parent.isAutoExpandPermitted()) {
			return;
		}
		monitor.checkCancelled();
		List<GTreeNode> allChildren = parent.getChildren();
		if (allChildren.size() == 0) {
			return;
		}
		TreePath treePath = parent.getTreePath();
		if (!jTree.isExpanded(treePath)) {
			expandPath(treePath, monitor);
		}
		foreach (GTreeNode child in allChildren) {
			monitor.checkCancelled();
			expandNode(child, false, monitor);
		}
		monitor.incrementProgress(1); // TODO: total node count is unknown
	}

	private void expandPath(TreePath treePath, TaskMonitor monitor) {
		runOnSwingThread(new _Anon_Runnable_1());
	}


	internal class _Anon_Runnable_1 : Runnable
	{

			/* @Override */
			public void run() {
				if (monitor.isCancelled()) {
					return; // we can be cancelled while waiting for Swing to run us
				}

				jTree.expandPath(treePath);
			}
		
	}

}
